// index.js — Story page: vowel swatches (play WAV, draw tube + film), butterfly voices.
// Data only from web/data/*.json (generated by python -m tools.build_all); no physics recomputed here.
import { fitCanvas, ramp } from "./plot.js";

const $ = (s) => document.querySelector(s);
const state = { group: "men", mode: "ideal", map: "full", ill: "D65", vowels: [], sel: null, playing: null, t0: 0,
  sounds: [], ssel: null };
const audio = new Audio();
audio.preload = "auto";

// Colour set of a vowel for the current mapping (CONTRACT §4b: full-band default, brief on toggle) and film mode.
// Falls back to the brief colours if vowels.json predates colours_full.
function colourSet(v) {
  const brief = state.mode === "ideal" ? v.colours : (v.colours_real || v.colours);
  if (state.map !== "full") return brief;
  const full = state.mode === "ideal" ? v.colours_full : (v.colours_full_real || v.colours_full);
  return full || brief;
}

function colourOf(v, quantity = "T") {
  const set = colourSet(v);
  const c = (set && (set[state.ill] || set.D65)) || {};
  return c[quantity] || "#444";
}

function play(src, tag) {
  try {
    audio.pause();
    audio.src = src;
    audio.currentTime = 0;
    state.playing = tag; state.t0 = performance.now();
    audio.play().catch(() => { $("#now").textContent = "Audio could not play (browser blocked autoplay or file missing)."; });
  } catch (e) { /* ignore */ }
}
audio.addEventListener("ended", () => { state.playing = null; });

function renderSwatches() {
  const box = $("#swatches");
  const items = state.vowels.filter((v) => v.group === state.group);
  box.innerHTML = "";
  for (const v of items) {
    const b = document.createElement("button");
    b.className = "sw" + (state.sel === v ? " on" : "");
    const t = colourOf(v, "T"), r = colourOf(v, "R");
    b.innerHTML = `<div class="pair"><i style="background:${r}; box-shadow:0 0 16px ${r}66" title="reflected">R</i>` +
      `<i style="background:${t}; box-shadow:0 0 16px ${t}66" title="transmitted">T</i></div>` +
      `<div class="ipa">/${v.ipa}/</div><div class="ex">${v.example}</div>`;
    b.title = `/${v.ipa}/ as in "${v.example}" — F1 ${Math.round(v.F1)} Hz, F2 ${Math.round(v.F2)} Hz — T ${t}, R ${r}`;
    b.addEventListener("click", () => select(v, true));
    box.appendChild(b);
  }
}

function select(v, withSound) {
  state.sel = v;
  renderSwatches();
  const t = colourOf(v, "T");
  const set = colourSet(v);
  const Y = set && set[state.ill] ? set[state.ill].Y_T : null;
  const nArr = state.mode === "ideal" ? v.n_ideal : v.n_real;
  const nMax = Math.max(...nArr.slice(1, -1));
  $("#now").innerHTML = `<b>/${v.ipa}/ “${v.example}”</b> (${v.group}) · F1 ${Math.round(v.F1)} Hz · F2 ${Math.round(v.F2)} Hz · ` +
    `${state.map === "full" ? "full-band" : "brief"} · reflected <span class="mono" style="color:${colourOf(v, "R")}">${colourOf(v, "R")}</span>` +
    ` · transmitted <span class="mono" style="color:${t}">${t}</span>` +
    (Y != null ? ` · true transmittance Y = ${Y.toFixed(Y < 1 ? 2 : 1)} %` : "") +
    ` · largest layer index n = ${nMax.toFixed(nMax > 10 ? 0 : 2)} <span class="badge ${state.mode === "ideal" ? "exact" : "approx"}">${state.mode}</span>`;
  if (withSound && v.audio) play(v.audio, v);
  drawHero();
}

function drawHero(now = performance.now()) {
  const cv = $("#hero-canvas");
  const { ctx, w, h } = fitCanvas(cv);
  const v = state.sel;
  if (!v) return;
  const col = colourOf(v, "T"), colR = colourOf(v, "R");
  const pulse = state.playing === v ? ((now - state.t0) / 1000) : null;

  // --- tube (glottis left -> lips right), radius = sqrt(area); areas[0..p-1] sections, areas[p] radiation
  const A = v.areas.slice(0, -1);
  const rMax = Math.sqrt(Math.max(...A));
  const tx = 18, tw = w * 0.56 - 30, cy = h * 0.5, Rpx = h * 0.36;
  const sw = tw / A.length;
  ctx.save();
  ctx.shadowColor = col; ctx.shadowBlur = 26;
  ctx.fillStyle = col + "55"; ctx.strokeStyle = col; ctx.lineWidth = 1.5;
  ctx.beginPath();
  A.forEach((a, i) => { const r = Math.max(1.5, Rpx * Math.sqrt(a) / rMax); ctx.lineTo(tx + i * sw, cy - r); ctx.lineTo(tx + (i + 1) * sw, cy - r); });
  for (let i = A.length - 1; i >= 0; i--) { const r = Math.max(1.5, Rpx * Math.sqrt(A[i]) / rMax); ctx.lineTo(tx + (i + 1) * sw, cy + r); ctx.lineTo(tx + i * sw, cy + r); }
  ctx.closePath(); ctx.fill(); ctx.stroke();
  ctx.restore();
  if (pulse != null) { // travelling pressure pulse (artistic)
    const x = tx + ((pulse * 0.9) % 1) * tw;
    const g = ctx.createRadialGradient(x, cy, 0, x, cy, 40);
    g.addColorStop(0, "rgba(255,255,255,0.55)"); g.addColorStop(1, "rgba(255,255,255,0)");
    ctx.fillStyle = g; ctx.fillRect(x - 40, cy - 40, 80, 80);
  }
  ctx.fillStyle = "#9aa1b5"; ctx.font = "11px Segoe UI, sans-serif"; ctx.textAlign = "left";
  ctx.fillText("glottis", tx, h - 12); ctx.textAlign = "right"; ctx.fillText("lips", tx + tw, h - 12);
  ctx.textAlign = "center"; ctx.fillText("vocal tract · radius ∝ √area", tx + tw / 2, 16);

  // --- film stack (light enters from top), colour by log n (artistic), equal optical thickness
  const n = state.mode === "ideal" ? v.n_ideal : v.n_real;
  const layers = n.slice(1, -1);
  const lnMax = Math.log(Math.max(...n));
  const fx = w * 0.64, fw = w * 0.3, fy = 46, fh = h - 92;
  const lh = fh / layers.length;
  layers.forEach((ni, i) => {
    ctx.fillStyle = ramp(lnMax > 0 ? Math.log(ni) / lnMax : 0);
    ctx.fillRect(fx, fy + i * lh, fw, lh - 1);
  });
  // incident white light, reflected and transmitted colour
  ctx.strokeStyle = "rgba(255,255,255,0.8)"; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(fx + fw * 0.3, 6); ctx.lineTo(fx + fw * 0.42, fy - 2); ctx.stroke();
  ctx.save(); ctx.shadowBlur = 18;
  ctx.shadowColor = colR; ctx.strokeStyle = colR;
  ctx.beginPath(); ctx.moveTo(fx + fw * 0.46, fy - 2); ctx.lineTo(fx + fw * 0.6, 6); ctx.stroke();
  ctx.shadowColor = col; ctx.strokeStyle = col; ctx.lineWidth = 5;
  ctx.beginPath(); ctx.moveTo(fx + fw * 0.44, fy + fh + 2); ctx.lineTo(fx + fw * 0.56, h - 4); ctx.stroke();
  ctx.restore();
  ctx.fillStyle = "#9aa1b5"; ctx.textAlign = "center";
  ctx.save(); ctx.translate(fx - 12, fy + fh / 2); ctx.rotate(-Math.PI / 2);
  ctx.fillText("thin film · colour ∝ log n", 0, 0); ctx.restore();
  ctx.textAlign = "left";
  ctx.fillText("R", fx + fw * 0.64, 18); ctx.fillText("T", fx + fw * 0.6, h - 8);
  if (state.playing === v) requestAnimationFrame(drawHero);
}

function renderButterflies(items) {
  const box = $("#bflies");
  box.innerHTML = "";
  for (const b of items) {
    const row = document.createElement("div");
    row.className = "bfly";
    const lut = (b.lut && b.lut.rgb) || [];
    const grad = lut.length ? `linear-gradient(90deg, ${lut.join(", ")})` : "#333";
    const F = (b.F || []).filter((f) => f < 4000).map((f) => Math.round(f));
    row.innerHTML = `<div><b>${b.name}</b> <span class="badge approx">${b.label || "approximate"}</span><br>` +
      `<span class="muted" style="font-size:.83rem">${b.n.length - 2} layers · ${F.length ? "formants ≈ " + F.join(", ") + " Hz" : "no sharp formants below 4 kHz"}</span></div>` +
      `<button class="btn" ${b.audio ? "" : "disabled"}>▶ listen</button><div class="strip" style="background:${grad}" title="reflected colour vs viewing angle 0°→80°"></div>`;
    row.querySelector("button").addEventListener("click", () => { if (b.audio) { play(b.audio, b); drawHero(); } });
    box.appendChild(row);
  }
}

// ----------------------------------------------------------------------------- "Every sound has a colour"
// Data: web/data/sounds.json (CONTRACT §7c, python -m tools.build_sounds). Never throws on missing fields.
const esc = (x) => String(x == null ? "" : x).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const HEX = /^#[0-9a-fA-F]{6}$/;
const safeHex = (h) => (typeof h === "string" && HEX.test(h) ? h : "#444444");

function soundColour(s, q) {
  try {
    const m = s.colours[state.map] || s.colours.full;
    const c = m[state.mode === "ideal" ? "ideal" : "realizable"][q];
    return safeHex(c && c.hex);
  } catch (e) { return "#444444"; }
}

function stripCss(s) {
  const st = (Array.isArray(s.strip) ? s.strip : []).map(safeHex);
  if (!st.length) return "#333";
  if (st.length === 1) return st[0];
  return `linear-gradient(90deg, ${st.map((c, i) => `${c} ${(100 * i / (st.length - 1)).toFixed(1)}%`).join(", ")})`;
}

function soundTile(s) {
  const b = document.createElement("button");
  b.className = "sw snd" + (state.ssel === s ? " on" : "");
  const r = soundColour(s, "R"), t = soundColour(s, "T");
  b.innerHTML = `<div class="pair"><i style="background:${r}" title="reflected">R</i><i style="background:${t}" title="transmitted">T</i></div>` +
    `<div class="ipa">[${esc(s.ipa)}]</div><div class="ex">${esc(s.example)}</div>` +
    `<div class="snd-strip" style="background:${stripCss(s)}"></div>`;
  b.title = `[${s.ipa}] ${s.name} — R ${r}, T ${t} — click to hear the recording`;
  b.addEventListener("click", () => selectSound(s, true));
  return b;
}

function renderSounds() {
  const V = $("#snd-vowels"), C = $("#snd-cons");
  if (!V || !C) return;
  V.innerHTML = ""; C.innerHTML = "";
  const order = ["plosive", "nasal", "fricative", "lateral", "approximant"];
  const cons = state.sounds.filter((s) => s.kind !== "vowel")
    .sort((a, b) => order.indexOf(a.class) - order.indexOf(b.class));
  for (const s of state.sounds.filter((x) => x.kind === "vowel")) V.appendChild(soundTile(s));
  for (const s of cons) C.appendChild(soundTile(s));
  if (!V.children.length) V.innerHTML = `<div class="empty">No vowel recordings in data/sounds.json.</div>`;
  if (!C.children.length) C.innerHTML = `<div class="empty">No consonant recordings in data/sounds.json.</div>`;
}

function selectSound(s, withSound) {
  state.ssel = s;
  renderSounds();
  const box = $("#snd-detail");
  if (!box || !s) return;
  const r = soundColour(s, "R"), t = soundColour(s, "T");
  const at = s.attribution || {};
  const F = (s.lpc_formants || []).filter((f) => f < 5000).map((f) => Math.round(f));
  const page = typeof at.page === "string" && at.page.startsWith("https://") ? at.page : null;
  box.innerHTML =
    `<div class="pair big"><i style="background:${r}">R</i><i style="background:${t}">T</i></div>` +
    `<div class="snd-info"><b>[${esc(s.ipa)}]</b> ${esc(s.name)} · as in “${esc(s.example)}” ` +
    `<span class="badge ${s.kind === "vowel" ? "exact" : "approx"}">${esc(s.class)}${s.voiced ? ", voiced" : ", voiceless"}</span><br>` +
    `<span class="muted">${state.map === "full" ? "full-band" : "brief"} · ${state.mode === "ideal" ? "ideal" : "realizable"} film · ` +
    `reflected <span class="mono">${r}</span> · transmitted <span class="mono">${t}</span> · ` +
    `${esc(s.frames_used)} of ${esc(s.frames_total)} frames used (${esc(s.segment_note || s.rule)})` +
    `${F.length ? " · LPC peaks ≈ " + F.join(", ") + " Hz" : ""}</span>` +
    `<div class="snd-strip wide" style="background:${stripCss(s)}" title="colour of each frame, in time order (full-band, realizable, reflected)"></div>` +
    `<span class="muted" style="font-size:.8rem">Recording: ${page ? `<a href="${esc(page)}" target="_blank" rel="noopener">${esc(at.title || "Wikimedia Commons")}</a>` : esc(at.title || "")}` +
    ` by ${esc(at.author || "unknown")}, ${esc(at.license || "")}</span></div>`;
  if (withSound && s.audio) play(s.audio, s);
}

// Mapping / film-mode choices are shared by every .seg[data-key] on the page (vowel palette + sounds section).
function setChoice(key, val) {
  state[key] = val;
  for (const seg of document.querySelectorAll(`.seg[data-key="${key}"]`))
    for (const x of seg.querySelectorAll("button")) x.classList.toggle("on", (x.dataset.v || x.dataset.m) === val);
  renderSwatches(); if (state.sel) select(state.sel, false);
  renderSounds(); if (state.ssel) selectSound(state.ssel, false);
}

function wireChoices() {
  for (const seg of document.querySelectorAll(".seg[data-key]")) {
    seg.addEventListener("click", (e) => {
      const b = e.target.closest("button"); if (!b) return;
      setChoice(seg.dataset.key, b.dataset.v || b.dataset.m);
    });
  }
}

function wireSeg(id, key, attr) {
  $(id).addEventListener("click", (e) => {
    const b = e.target.closest("button"); if (!b) return;
    for (const x of $(id).querySelectorAll("button")) x.classList.toggle("on", x === b);
    state[key] = b.dataset[attr];
    if (key === "group") state.sel = state.vowels.find((v) => v.group === state.group && v.vowel === (state.sel && state.sel.vowel)) || state.vowels.find((v) => v.group === state.group);
    renderSwatches(); if (state.sel) select(state.sel, false);
  });
}

async function main() {
  wireSeg("#grp", "group", "g");
  wireChoices();
  $("#ill").addEventListener("change", (e) => { state.ill = e.target.value; renderSwatches(); if (state.sel) select(state.sel, false); });
  window.addEventListener("resize", () => drawHero());
  try {
    const vj = await (await fetch("data/vowels.json")).json();
    state.vowels = vj.items || [];
    state.sel = state.vowels.find((v) => v.group === "men" && v.vowel === "ah") || state.vowels[0];
    renderSwatches();
    if (state.sel) select(state.sel, false);
  } catch (e) {
    $("#swatches").innerHTML = `<div class="empty">Could not load data/vowels.json — run <code>python -m tools.build_all</code> and serve the <code>web/</code> folder (start_demo.bat).</div>`;
  }
  try {
    const bj = await (await fetch("data/butterflies.json")).json();
    renderButterflies(bj.items || []);
  } catch (e) {
    $("#bflies").innerHTML = `<div class="empty">data/butterflies.json not found.</div>`;
  }
  try {
    const r = await fetch("data/sounds.json");
    if (!r.ok) throw new Error(String(r.status));
    const sj = await r.json();
    state.sounds = (sj.items || []).filter((s) => s && s.colours && s.id);
    renderSounds();
    if (state.sounds.length) selectSound(state.sounds.find((s) => s.ipa === "s") || state.sounds[0], false);
    else $("#snd-detail").innerHTML = `<div class="empty">data/sounds.json has no sounds yet — run <code>python -m tools.fetch_ipa</code> then <code>python -m tools.build_sounds</code>.</div>`;
  } catch (e) {
    $("#snd-detail").innerHTML = `<div class="empty">Real-recording colours are not available (data/sounds.json missing) — run <code>python -m tools.fetch_ipa</code> and <code>python -m tools.build_sounds</code>.</div>`;
    renderSounds();
  }
}
main();
